mapper.delete:
DELETE FROM wall_post_action
WHERE post_no = #{postNo}
  AND user_uid = #{userUid}
  AND action_type = #{actionType}

mapper.select:
SELECT COUNT(*)
FROM wall_post
WHERE user_id = #{userId}
AND is_deleted = 0
AND create_time >= #{dayStart}
AND create_time <= #{dayEnd}

SELECT , 0 AS isTop, 0 AS isTiming, 0 AS isLike, 0 AS isCollect FROM wall_post wp LEFT JOIN user u ON wp.user_id = u.id LEFT JOIN wall_category wc ON wp.category_id = wc.id AND wc.is_deleted = 0 LEFT JOIN wall_category_sub wcs ON wp.sub_category_id = wcs.id AND wcs.is_deleted = 0 WHERE wp.is_deleted = 0 AND (wp.publish_time IS NULL OR wp.publish_time <= NOW()) AND (
wp.content LIKE CONCAT('%', #{kw}, '%') OR (wp.is_anonymous = 0 AND wp.nickname LIKE CONCAT('%', #{kw}, '%')) OR wc.name LIKE CONCAT('%', #{kw}, '%') OR wcs.name LIKE CONCAT('%', #{kw}, '%')
) ORDER BY wp.create_time DESC LIMIT #{limit}
